:root { --wp-block-synced-color: #7a00df; --wp-block-synced-color--rgb: 122, 0, 223; --wp-bound-block-color: var(--wp-block-synced-color); --wp-editor-canvas-background: #ddd; --wp-admin-theme-color: #007cba; --wp-admin-theme-color--rgb: 0, 124, 186; --wp-admin-theme-color-darker-10: rgb(0, 107, 160.5); --wp-admin-theme-color-darker-10--rgb: 0, 107, 160.5; --wp-admin-theme-color-darker-20: #005a87; --wp-admin-theme-color-darker-20--rgb: 0, 90, 135; --wp-admin-border-width-focus: 2px; }
@media (min-resolution: 192dpi) {
  :root { --wp-admin-border-width-focus: 1.5px; }
}
.wp-element-button { cursor: pointer; }
:root .has-very-light-gray-background-color { background-color: rgb(238, 238, 238); }
:root .has-very-dark-gray-background-color { background-color: rgb(49, 49, 49); }
:root .has-very-light-gray-color { color: rgb(238, 238, 238); }
:root .has-very-dark-gray-color { color: rgb(49, 49, 49); }
:root { }
:root .has-vivid-green-cyan-to-vivid-cyan-blue-gradient-background { background: linear-gradient(135deg, rgb(0, 208, 132) 0%, rgb(6, 147, 227) 100%); }
:root .has-purple-crush-gradient-background { background: linear-gradient(135deg, rgb(52, 226, 228) 0%, rgb(71, 33, 251) 50%, rgb(171, 29, 254) 100%); }
:root .has-hazy-dawn-gradient-background { background: linear-gradient(135deg, rgb(250, 172, 168) 0%, rgb(218, 208, 236) 100%); }
:root .has-subdued-olive-gradient-background { background: linear-gradient(135deg, rgb(250, 250, 225) 0%, rgb(103, 166, 113) 100%); }
:root .has-atomic-cream-gradient-background { background: linear-gradient(135deg, rgb(253, 215, 154) 0%, rgb(0, 74, 89) 100%); }
:root .has-nightshade-gradient-background { background: linear-gradient(135deg, rgb(51, 9, 104) 0%, rgb(49, 205, 207) 100%); }
:root .has-midnight-gradient-background { background: linear-gradient(135deg, rgb(2, 3, 129) 0%, rgb(40, 116, 252) 100%); }
:root { --wp--preset--font-size--normal: 16px; --wp--preset--font-size--huge: 42px; }
.has-regular-font-size { font-size: 1em; }
.has-larger-font-size { font-size: 2.625em; }
.has-normal-font-size { font-size: var(--wp--preset--font-size--normal); }
.has-huge-font-size { font-size: var(--wp--preset--font-size--huge); }
:root .has-text-align-center { text-align: center; }
:root .has-text-align-left { text-align: left; }
:root .has-text-align-right { text-align: right; }
.has-fit-text { white-space: nowrap !important; }
#end-resizable-editor-section { display: none; }
.aligncenter { clear: both; }
.items-justified-left { justify-content: flex-start; }
.items-justified-center { justify-content: center; }
